from qiskit import QuantumCircuit, QuantumRegister
import math

def solve(n: int, m: int, S: list[int]) -> QuantumCircuit:
    x = QuantumRegister(n)
    y = QuantumRegister(m)
    qc = QuantumCircuit(x, y)

    # QFT on y, little endian: y[0] is LSB
    for i in range(m):
        qc.h(y[i])
        for j in range(i + 1, m):
            angle = 2 * math.pi / (2 ** (j - i + 1))
            qc.cp(angle, y[j], y[i])

    # controlled phases for f(x) = sum_k S_k x_k
    mod = 1 << m
    for k in range(n):
        s = S[k] % mod
        if s == 0:
            continue
        for j in range(m):
            denom = 1 << (m - j)          # 2^{m-j}
            angle = 2 * math.pi * s / denom
            angle = angle % (2 * math.pi)
            if angle < 1e-12:
                continue
            qc.cp(angle, x[k], y[j])

    # inverse QFT on y
    for i in range(m - 1, -1, -1):
        for j in range(i + 1, m):
            angle = -2 * math.pi / (2 ** (j - i + 1))
            qc.cp(angle, y[j], y[i])
        qc.h(y[i])

    return qc
